/**
 * The repository: every read and write the app performs against local data.
 *
 * Reads return `@lexpad/core` shapes, so a screen can hand them straight
 * to the engine. Writes apply the change locally **and** append to the
 * outbox in one transaction, which is what makes an offline edit durable
 * and eventually pushed exactly once.
 */
import { dayIndex, type Progress, type Settings, type Streak, type Word } from '@lexpad/core';
import {
  db,
  getMeta,
  setMeta,
  type OutboxItem,
  type StoredConfusion,
  type StoredDayStat,
  type StoredNotebook,
  type StoredProgress,
  type StoredWord,
  type LexpadDb,
} from './schema.js';
import { newId } from '@/lib/id.js';

/** The tables a write may touch, for Dexie's transaction scope. */
/** Every table a mutation may touch, so one transaction covers them all. */
export function writableTables(database: LexpadDb) {
  return [
    database.words,
    database.progress,
    database.notebooks,
    database.confusions,
    database.dayStats,
    database.meta,
    database.outbox,
  ];
}

/** Joins a stored word with its learning state. */
function toWord(stored: StoredWord, progress?: StoredProgress): Word {
  if (!progress) return stored;
  const { wordId: _wordId, ...state } = progress;
  return { ...stored, progress: state };
}

/** Every word of a notebook, with progress attached. */
export async function listWords(notebookId: string, database: LexpadDb = db): Promise<Word[]> {
  const stored = await database.words.where('notebookId').equals(notebookId).toArray();
  // Only this notebook's rows. Reading the whole table loaded every
  // notebook's progress, and inside a live query it made a grade anywhere
  // re-run every screen.
  const progress = await database.progress.bulkGet(stored.map((word) => word.id));
  return stored.map((word, index) => toWord(word, progress[index]));
}

/** How many words a notebook has, without reading them. */
export async function countWords(notebookId: string, database: LexpadDb = db): Promise<number> {
  return database.words.where('notebookId').equals(notebookId).count();
}

/** One word with its learning state, or undefined when it is not local. */
export async function getWord(wordId: string, database: LexpadDb = db): Promise<Word | undefined> {
  const [stored, progress] = await Promise.all([database.words.get(wordId), database.progress.get(wordId)]);
  return stored === undefined ? undefined : toWord(stored, progress);
}

/** The notebooks the user can see, in their chosen order. */
export async function listNotebooks(database: LexpadDb = db): Promise<StoredNotebook[]> {
  return database.notebooks.orderBy('sortOrder').toArray();
}

/** The notebook the UI is currently showing, defaulting to the default one. */
export async function getActiveNotebook(database: LexpadDb = db): Promise<StoredNotebook | undefined> {
  const chosen = await getMeta('activeNotebook', database);
  if (chosen !== null) {
    const notebook = await database.notebooks.get(chosen);
    if (notebook) return notebook;
  }
  const all = await listNotebooks(database);
  return all.find((notebook) => notebook.isDefault) ?? all[0];
}

/** Switches the notebook the UI shows. */
export async function setActiveNotebook(notebookId: string, database: LexpadDb = db): Promise<void> {
  await setMeta('activeNotebook', notebookId, database);
}

/** Confusion pair counts, keyed as the engine expects. */
export async function loadConfusions(database: LexpadDb = db): Promise<Map<string, number>> {
  const rows = await database.confusions.toArray();
  return new Map(rows.map((row) => [row.key, row.count]));
}

/** The user's settings, or null before the first sync. */
export async function loadSettings(database: LexpadDb = db): Promise<Settings | null> {
  return getMeta('settings', database);
}

/** The user's streak. */
export async function loadStreak(database: LexpadDb = db): Promise<Streak> {
  return getMeta('streak', database);
}

/** Review totals for the last `days` days, oldest first and zero-filled. */
export async function loadHistory(
  days: number,
  timeZone: string,
  now: Date = new Date(),
  database: LexpadDb = db,
): Promise<StoredDayStat[]> {
  const today = dayIndex(now, timeZone);
  const from = today - days + 1;
  const rows = await database.dayStats.where('day').aboveOrEqual(from).toArray();
  const byDay = new Map(rows.map((row) => [row.day, row]));
  const out: StoredDayStat[] = [];
  for (let day = from; day <= today; day++) {
    out.push(byDay.get(day) ?? { day, reviewed: 0, correct: 0, newWords: 0 });
  }
  return out;
}

/** A change the app wants to make locally and eventually push. */
export interface Mutation {
  entity: OutboxItem['entity'];
  entityId: string;
  op: OutboxItem['op'];
  /** The body the API expects for this entity, or omitted for a delete. */
  payload?: unknown;
  /**
   * Builds the body inside the transaction, for a change whose result
   * depends on what is already stored. Wins over `payload` when given.
   */
  buildPayload?: (database: LexpadDb) => Promise<unknown>;
  /** Applies the change to the local tables. Runs inside the transaction. */
  apply: (database: LexpadDb) => Promise<void>;
}

/**
 * Applies a change locally and queues it for the server, atomically. If the
 * local write fails nothing is queued; if the transaction commits the change
 * is durable and will be pushed even if the app is closed immediately.
 */
export async function mutate(mutation: Mutation, database: LexpadDb = db): Promise<void> {
  const clientTs = new Date().toISOString();
  const baseCursor = await getMeta('cursor', database);
  await database.transaction('rw', writableTables(database), async () => {
    await mutation.apply(database);
    const payload = mutation.buildPayload ? await mutation.buildPayload(database) : mutation.payload;
    const item: OutboxItem = {
      clientId: newId(),
      entity: mutation.entity,
      entityId: mutation.entityId,
      op: mutation.op,
      clientTs,
      baseCursor,
      attempts: 0,
      ...(payload === undefined ? {} : { payload }),
    };
    await database.outbox.add(item);
  });
}

/** How many changes are waiting to be pushed. */
export async function outboxSize(database: LexpadDb = db): Promise<number> {
  return database.outbox.filter((item) => item.parked !== true).count();
}

/**
 * Whether anything is waiting to be pushed. Stops at the first queued item
 * rather than counting them all, for a screen that only shows that there is.
 */
export async function hasQueued(database: LexpadDb = db): Promise<boolean> {
  return (await database.outbox.filter((item) => item.parked !== true).first()) !== undefined;
}

/** The queued changes, in the order they were made, leaving parked ones aside. */
export async function outboxItems(limit: number, database: LexpadDb = db): Promise<OutboxItem[]> {
  return database.outbox
    .orderBy('seq')
    .filter((item) => item.parked !== true)
    .limit(limit)
    .toArray();
}

/** How many changes were set aside after repeated failures. */
export async function parkedCount(database: LexpadDb = db): Promise<number> {
  return database.outbox.filter((item) => item.parked === true).count();
}

/** Puts every parked change back in the queue with a clean slate. */
export async function unparkAll(database: LexpadDb = db): Promise<number> {
  const parked = await database.outbox.filter((item) => item.parked === true).toArray();
  for (const item of parked) {
    if (item.seq !== undefined) await database.outbox.update(item.seq, { parked: false, attempts: 0 });
  }
  return parked.length;
}

/** Sets changes aside with the reason; see OutboxItem.parked. */
export async function parkOutboxItems(
  seqs: number[],
  database: LexpadDb = db,
  reason?: string,
): Promise<void> {
  for (const seq of seqs) {
    await database.outbox.update(
      seq,
      reason === undefined ? { parked: true } : { parked: true, lastError: reason },
    );
  }
}

/** Removes queued changes the server has accepted. */
export async function dropOutboxItems(seqs: number[], database: LexpadDb = db): Promise<void> {
  await database.outbox.bulkDelete(seqs);
}

/** Records a failed push attempt so the worker can back off. */
export async function markOutboxAttempt(seq: number, error: string, database: LexpadDb = db): Promise<void> {
  const item = await database.outbox.get(seq);
  if (!item) return;
  await database.outbox.update(seq, { attempts: item.attempts + 1, lastError: error });
}

/** Replaces a word's stored row, keeping its learning state untouched. */
export async function putWord(word: Word, database: LexpadDb = db): Promise<void> {
  const { progress, ...stored } = word;
  await database.words.put(stored);
  if (progress) await putProgress(word.id, progress, database);
}

/** Replaces a word's learning state. */
export async function putProgress(
  wordId: string,
  progress: Progress,
  database: LexpadDb = db,
): Promise<void> {
  await database.progress.put({ wordId, ...progress });
}

/** Removes a word and its learning state. */
export async function deleteWordLocal(wordId: string, database: LexpadDb = db): Promise<void> {
  await Promise.all([database.words.delete(wordId), database.progress.delete(wordId)]);
}

/** Replaces a notebook's stored row. */
export async function putNotebook(notebook: StoredNotebook, database: LexpadDb = db): Promise<void> {
  await database.notebooks.put(notebook);
}

/** Removes a notebook and every word in it. */
export async function deleteNotebookLocal(notebookId: string, database: LexpadDb = db): Promise<void> {
  const ids = await database.words.where('notebookId').equals(notebookId).primaryKeys();
  await Promise.all([
    database.notebooks.delete(notebookId),
    database.words.bulkDelete(ids),
    database.progress.bulkDelete(ids),
  ]);
}

/** Replaces a confusion pair count. */
export async function putConfusion(row: StoredConfusion, database: LexpadDb = db): Promise<void> {
  await database.confusions.put(row);
}

/** Adds to a day's totals, creating the row when it is the first review. */
export async function bumpDayStat(
  day: number,
  delta: { reviewed?: number; correct?: number; newWords?: number },
  database: LexpadDb = db,
): Promise<void> {
  const existing = (await database.dayStats.get(day)) ?? { day, reviewed: 0, correct: 0, newWords: 0 };
  await database.dayStats.put({
    day,
    reviewed: Math.max(0, existing.reviewed + (delta.reviewed ?? 0)),
    correct: Math.max(0, existing.correct + (delta.correct ?? 0)),
    newWords: Math.max(0, existing.newWords + (delta.newWords ?? 0)),
  });
}

/** Stores the user's settings locally. */
export async function putSettings(settings: Settings, database: LexpadDb = db): Promise<void> {
  await setMeta('settings', settings, database);
}

/** Stores the user's streak locally. */
export async function putStreak(streak: Streak, database: LexpadDb = db): Promise<void> {
  await setMeta('streak', streak, database);
}

/**
 * What the app is showing: one notebook, or all of them at once.
 *
 * It is one choice for the whole app rather than a setting per screen.
 * Somebody who keeps an English notebook and a Persian one is either
 * working on one language today or working on both, and having Today
 * answer that differently from the notebook page — or from a session —
 * is three answers to one question.
 *
 * The choice is stored in `practiceScope`, which is what it was called
 * when it only governed sessions. The name is on the wire and on devices
 * that have not updated, so it stays; what it means has widened.
 */
export async function inView(database: LexpadDb = db): Promise<{
  /** Every notebook the app is currently showing, in order. */
  notebooks: StoredNotebook[];
  /**
   * The one to write into, and the one whose name the header carries: the
   * notebook being shown, or — when every notebook is in view — the default
   * one, since nothing else would answer where a new word goes.
   */
  showing: StoredNotebook | undefined;
  /** Whether all of them are in view. False whenever there is only one. */
  all: boolean;
}> {
  const [settings, everything, active] = await Promise.all([
    loadSettings(database),
    listNotebooks(database),
    getActiveNotebook(database),
  ]);
  // One notebook is never "all notebooks": the phrase would be true and
  // useless, and every screen would carry a distinction nobody has.
  const all = settings?.practiceScope === 'all' && everything.length > 1;
  // With everything in view there is no notebook being shown, so a new word
  // needs a home: the default one. It is the only answer that does not
  // depend on which notebook happened to be open last.
  const writing = all ? (everything.find((one) => one.isDefault) ?? everything[0]) : active;
  return {
    notebooks: all ? everything : active ? [active] : [],
    showing: writing,
    all,
  };
}

/** Every word in view, across one notebook or all of them. */
export async function wordsInView(database: LexpadDb = db): Promise<Word[]> {
  const { notebooks } = await inView(database);
  if (notebooks.length === 1 && notebooks[0] !== undefined) {
    return listWords(notebooks[0].id, database);
  }
  const lists = await Promise.all(notebooks.map((notebook) => listWords(notebook.id, database)));
  return lists.flat();
}
