/** Small presentation helpers shared by screens. */
import { t } from '@/i18n/index.js';

/** The greeting for the local hour. */
export function greeting(now: Date): string {
  const hour = now.getHours();
  if (hour < 12) return t('today.greetingMorning');
  if (hour < 18) return t('today.greetingAfternoon');
  return t('today.greetingEvening');
}

/** A day index rendered as Today, Yesterday or a short date. */
export function dayLabel(day: number, today: number): string {
  if (day === today) return t('notebook.today');
  if (day === today - 1) return t('notebook.yesterday');
  return new Date(day * 86_400_000).toLocaleDateString(undefined, { day: 'numeric', month: 'short' });
}

/** An ISO date (`YYYY-MM-DD`) rendered the same way. */
export function isoDayLabel(iso: string, todayIso: string): string {
  if (iso === todayIso) return t('notebook.today');
  const day = Date.parse(`${iso}T00:00:00Z`) / 86_400_000;
  const todayDay = Date.parse(`${todayIso}T00:00:00Z`) / 86_400_000;
  return dayLabel(day, todayDay);
}

/** Accuracy as a whole percentage, or a dash when nothing was reviewed. */
export function accuracy(correct: number, reviewed: number): string {
  if (reviewed <= 0) return '—';
  return `${Math.round((correct / reviewed) * 100)}%`;
}

/**
 * How long ago something happened, the way a list of messages says it:
 * "Just now", "5 min ago", "3 h ago", "Yesterday", "4 days ago", then a
 * short date. An unparseable instant gives an empty string rather than
 * "Invalid Date".
 */
export function relativeTime(iso: string, now: Date = new Date()): string {
  const at = Date.parse(iso);
  if (Number.isNaN(at)) return '';
  const minutes = Math.floor((now.getTime() - at) / 60_000);
  if (minutes < 1) return t('time.justNow');
  if (minutes < 60) return t('time.minutesAgo', { count: minutes });
  const hours = Math.floor(minutes / 60);
  if (hours < 24) return t('time.hoursAgo', { count: hours });
  const days = Math.floor(hours / 24);
  if (days === 1) return t('notebook.yesterday');
  if (days < 7) return t('time.daysAgo', { count: days });
  return new Intl.DateTimeFormat(undefined, { day: 'numeric', month: 'short' }).format(new Date(at));
}

/** The IANA timezone the browser reports, for day-index maths. */
/**
 * A date somebody reads in a sentence: "3 January 2027".
 *
 * An unparseable string is handed back untouched rather than shown as
 * "Invalid Date" — a date the server sent that we cannot read is still
 * better information than an error word.
 */
export function longDate(iso: string): string {
  const when = new Date(iso);
  if (Number.isNaN(when.getTime())) return iso;
  return when.toLocaleDateString(undefined, { day: 'numeric', month: 'long', year: 'numeric' });
}

export function localTimeZone(): string {
  try {
    return Intl.DateTimeFormat().resolvedOptions().timeZone;
  } catch {
    return 'UTC';
  }
}

/** "today", "yesterday" or a short date, in the learner's locale: when a device or app was last used. */
export function lastSeenLabel(iso: string, now: number = Date.now()): string {
  const days = Math.floor((now - Date.parse(iso)) / 86_400_000);
  if (days <= 0) return t('notebook.today').toLowerCase();
  if (days === 1) return t('notebook.yesterday').toLowerCase();
  return new Intl.DateTimeFormat(undefined, { day: 'numeric', month: 'short' }).format(new Date(iso));
}
